r m=0, i, j, temp, temp2, right1, right2, left, right, looping;\n\tvar cbcleft, cbcleft2, cbcright, cbcright2\n\tvar endloop, loopinc;\n\tvar len = message.length;\n\tvar chunk = 0;\n\t//set up the loops for single and triple des\n\tvar iterations = keys.length == 32 ? 3 : 9; //single or triple des\n\tif (iterations == 3) {looping = encrypt ? new Array (0, 32, 2) : new Array (30, -2, -2);}\n\telse {looping = encrypt ? new Array (0, 32, 2, 62, 30, -2, 64, 96, 2) : new Array (94, 62, -2, 32, 64, 2, 30, -2, -2);}\n\t//pad the message depending on the padding parameter\n\tif (padding == 2) message += \" \"; //pad the message with spaces\n\telse if (padding == 1) {temp = 8-(len%8); message += String.fromCharCode (temp,temp,temp,temp,temp,temp,temp,temp); if (temp==8) len+=8;} //PKCS7 padding\n\telse if (!padding) message += \"\\0\\0\\0\\0\\0\\0\\0\\0\"; //pad the message out with null bytes\n\t//store the result here\n\tresult = \"\";\n\ttempresult = \"\";\n\tif (mode == 1) { //CBC mode\n\tcbcleft = (iv.charCodeAt(m++) << 24) | (iv.charCodeAt(m++) << 16) | (iv.charCodeAt(m++) << 8) | iv.charCodeAt(m++);\n\tcbcright = (iv.charCodeAt(m++) << 24) | (iv.charCodeAt(m++) << 16) | (iv.charCodeAt(m++) << 8) | iv.charCodeAt(m++);\n\tm=0;\n\t}\n\t//loop through each 64 bit chunk of the message\n\twhile (m < len) {\n\tleft = (message.charCodeAt(m++) << 24) | (message.charCodeAt(m++) << 16) | (message.charCodeAt(m++) << 8) | message.charCodeAt(m++);\n\tright = (message.charCodeAt(m++) << 24) | (message.charCodeAt(m++) << 16) | (message.charCodeAt(m++) << 8) | message.charCodeAt(m++);\n\t//for Cipher Block Chaining mode, xor the message with the previous result\n\tif (mode == 1) {if (encrypt) {left ^= cbcleft; right ^= cbcright;} else {cbcleft2 = cbcleft; cbcright2 = cbcright; cbcleft = left; cbcright = right;}}\n\t//first each 64 but chunk of the message must be permuted according to IP\n\ttemp = ((left >>> 4) ^ right) & 0x0f0f0f0f; right ^= temp; left ^= (temp << 4);\n\ttemp = ((left >>> 16) ^ right) & 0x0000ffff; right ^= temp; left ^= (temp << 16);\n\ttemp = ((right >>> 2) ^ left) & 0x33333333; left ^= temp; right ^= (temp << 2);\n\ttemp = ((right >>> 8) ^ left) & 0x00ff00ff; left ^= temp; right ^= (temp << 8);\n\ttemp = ((left >>> 1) ^ right) & 0x55555555; right ^= temp; left ^= (temp << 1);\n\tleft = ((left << 1) | (left >>> 31));\n\tright = ((right << 1) | (right >>> 31));\n\t//do this either 1 or 3 times for each chunk of the message\n\tfor (j=0; j<iterations; j+=3) {\n\tendloop = looping[j+1];\n\tloopinc = looping[j+2];\n\t//now go through and perform the encryption or decryption\n\tfor (i=looping[j]; i!=endloop; i+=loopinc) { //for efficiency\n\tright1 = right ^ keys[i];\n\tright2 = ((right >>> 4) | (right << 28)) ^ keys[i+1];\n\t//the result is attained by passing these bytes through the S selection functions\n\ttemp = left;\n\tleft = right;\n\tright = temp ^ (spfunction2[(right1 >>> 24) & 0x3f] | spfunction4[(right1 >>> 16) & 0x3f]\n\t| spfunction6[(right1 >>> 8) & 0x3f] | spfunction8[right1 & 0x3f]\n\t| spfunction1[(right2 >>> 24) & 0x3f] | spfunction3[(right2 >>> 16) & 0x3f]\n\t| spfunction5[(right2 >>> 8) & 0x3f] | spfunction7[right2 & 0x3f]);\n\t}\n\ttemp = left; left = right; right = temp; //unreverse left and right\n\t} //for either 1 or 3 iterations\n\t//move then each one bit to the right\n\tleft = ((left >>> 1) | (left << 31));\n\tright = ((right >>> 1) | (right << 31));\n\t//now perform IP-1, which is IP in the opposite direction\n\ttemp = ((left >>> 1) ^ right) & 0x55555555; right ^= temp; left ^= (temp << 1);\n\ttemp = ((right >>> 8) ^ left) & 0x00ff00ff; left ^= temp; right ^= (temp << 8);\n\ttemp = ((right >>> 2) ^ left) & 0x33333333; left ^= temp; right ^= (temp << 2);\n\ttemp = ((left >>> 16) ^ right) & 0x0000ffff; right ^= temp; left ^= (temp << 16);\n\ttemp = ((left >>> 4) ^ right) & 0x0f0f0f0f; right ^= temp; left ^= (temp << 4);\n\t//for Cipher Block Chaining mode, xor the message with the previous result\n\tif (mode == 1) {if (encrypt) {cbcleft = left; cbcright = right;} else {left ^= cbcleft2; right ^= cbcright2;}}\n\ttempresult += String.fromCharCode ((left>>>24), ((left>>>16) & 0xff), ((left>>>8) & 0xff), (left & 0xff), (right>>>24), ((right>>>16) & 0xff), ((right>>>8) & 0xff), (right & 0xff));\n\tchunk += 8;\n\tif (chunk == 512) {result += tempresult; tempresult = \"\"; chunk = 0;}\n\t} //for every 8 characters, or 64 bits in the message\n\t//return the result as an array\n\treturn result + tempresult;\n\t} //end of des\n\t//des_createKeys\n\t//this takes as input a 64 bit key (even though only 56 bits are used)\n\t//as an array of 2 integers, and returns 16 48 bit keys\n\tfunction des_createKeys (key) {\n\t//declaring this locally speeds things up a bit\n\tpc2bytes0 = new Array (0,0x4,0x20000000,0x20000004,0x10000,0x10004,0x20010000,0x20010004,0x200,0x204,0x20000200,0x20000204,0x10200,0x10204,0x20010200,0x20010204);\n\tpc2bytes1 = new Array (0,0x1,0x100000,0x100001,0x4000000,0x4000001,0x4100000,0x4100001,0x100,0x101,0x100100,0x100101,0x4000100,0x4000101,0x4100100,0x4100101);\n\tpc2bytes2 = new Array (0,0x8,0x800,0x808,0x1000000,0x1000008,0x1000800,0x1000808,0,0x8,0x800,0x808,0x1000000,0x1000008,0x1000800,0x1000808);\n\tpc2bytes3 = new Array (0,0x200000,0x8000000,0x8200000,0x2000,0x202000,0x8002000,0x8202000,0x20000,0x220000,0x8020000,0x8220000,0x22000,0x222000,0x8022000,0x8222000);\n\tpc2bytes4 = new Array (0,0x40000,0x10,0x40010,0,0x40000,0x10,0x40010,0x1000,0x41000,0x1010,0x41010,0x1000,0x41000,0x1010,0x41010);\n\tpc2bytes5 = new Array (0,0x400,0x20,0x420,0,0x400,0x20,0x420,0x2000000,0x2000400,0x2000020,0x2000420,0x2000000,0x2000400,0x2000020,0x2000420);\n\tpc2bytes6 = new Array (0,0x10000000,0x80000,0x10080000,0x2,0x10000002,0x80002,0x10080002,0,0x10000000,0x80000,0x10080000,0x2,0x10000002,0x80002,0x10080002);\n\tpc2bytes7 = new Array (0,0x10000,0x800,0x10800,0x20000000,0x20010000,0x20000800,0x20010800,0x20000,0x30000,0x20800,0x30800,0x20020000,0x20030000,0x2002080